package com.mcalvaro.mscatering.infrastructure.support;

import java.util.concurrent.atomic.AtomicInteger;

/**
 * Provides unique contract sequences for test fixtures so they never collide with
 * contract codes generated by data committed by other tests on the shared database.
 */
public final class TestContractSequence {

    private static final AtomicInteger SEQUENCE = new AtomicInteger(9000);

    private TestContractSequence() {}

    public static int next() {
        return SEQUENCE.incrementAndGet();
    }
}
